/**
 * Relief asset bridge and procedural fallback (3D-03).
 *
 * The 3D chain consumes its own carve bake (3D-17: `frontend/public/table/relief3d/`
 * + `relief3d.json`, generated by `frontend/tools/relief3d/bake-relief3d.mjs`)
 * as immutable, read-only input. The Task 4B relief atlases this module was
 * written against were retired from the tree on 2026-11-18 (AGENTS.md §5), so
 * there is no second source: the chain is `relief3d`, then the procedural cell.
 * This module turns that input into:
 *
 * 1. a validated, pinned manifest with a face-id -> atlas-rect lookup,
 * 2. one texture request per atlas (albedo sRGB, normal/height and AO/roughness
 *    linear, `flipY = false`, mipmaps, tier anisotropy), and
 * 3. a truthful failure path: a 64 x 64 procedural neutral cell per channel so
 *    the scene still renders, with `status: 'fallback'` and one warning.
 *
 * Two deliberate boundaries:
 *
 * - **No `three` import.** 3D-02 owns the dependency and the `Texture`
 *   construction. This module takes a {@link ReliefTextureFactory}; the host
 *   supplies the three implementation (decode the PNG at the requested size,
 *   build a `Texture`/`DataTexture` with the requested settings and drop it on
 *   `dispose`). That keeps the bridge testable in Node with no GPU and keeps
 *   the relief contract independent of renderer internals.
 * - **No 2.5D import.** Face ids come from `../contract`; the manifest's own
 *   `faces` keys are the runtime cross-check, so a glyph-master re-bake either
 *   matches the pin or degrades to the neutral cell. It cannot break the 3D
 *   view silently, and it cannot make the 3D view depend on 2.5D code.
 *
 * Pinning is by byte length *and* SHA-256 of the PNGs. The pins in
 * {@link PINNED_RELIEF_ATLASES} are copied from the committed manifest; the
 * tests read the committed files and assert the pins still match them, so the
 * pin cannot drift from the repo unnoticed.
 *
 * Orientation: cells are packed top-left origin, y down (`relief.json`'s
 * `coordinateSpace`), and the tile mesh authors its face UVs V-down, so the
 * normals' tangent basis (x right, y down, z out) is used as published with no
 * flip. The plate is the committed 0.64 x 0.89 unit rect (17.92 x 24.92 mm),
 * not the full 21 x 28 mm body.
 */

import { BAKED_TILE_FACE_IDS, isTileFaceId } from '../contract';
import type { QualityTier, ReliefStatus, TileFaceId } from '../contract';
import { TILE } from '../layoutConstants';
import { sha256HexSync } from './sha256';

/**
 * The relief manifest schema version this bridge understands. A different
 * version is a hard load error (and therefore the fallback), never a guess.
 */
export const RELIEF_VERSION = 1;

/** Manifest path relative to the app's `public/table/` directory. */
export const RELIEF_MANIFEST_PATH = 'table/relief.json';

/** The committed atlas grid: 37 cells of 256 x 340 px in a 6 x 7 atlas. */
export const RELIEF_RASTER = {
  cellWidth: 256,
  cellHeight: 340,
  columns: 6,
  rows: 7,
  atlasWidth: 1536,
  atlasHeight: 2380,
  faceCount: 37,
} as const;

/** The committed carved plate, in tile units (17.92 x 24.92 mm at 1 unit = 28 mm). */
export const RELIEF_PLATE_UNITS = [0.64, 0.89] as const;

/** The 37 baked face ids, in the committed atlas order. `blank` has no art. */
export const RELIEF_FACE_IDS: readonly TileFaceId[] = BAKED_TILE_FACE_IDS;

/** One atlas's pin: path relative to `public/table/`, size and PNG hash. */
export interface ReliefAtlasPin {
  readonly file: string;
  readonly width: number;
  readonly height: number;
  readonly bytes: number;
  readonly sha256: string;
}

/**
 * The 3D-owned carve channels (3D-17).
 *
 * `relief3d.json` bakes the *decal's* engraving (a 0.3 mm transition with the
 * wall inside the painted silhouette) into the normal/height and AO/roughness
 * atlases, and reuses the committed albedo because the paint does not depend on
 * the carve geometry. A mismatch is a hard load error, exactly as for the
 * committed set.
 *
 * **Unused cells carry the open face, and they must.** 37 faces fill 37 of the
 * grid's 42 cells, and the plate's UV maps [0, 1] onto the cell's exact border,
 * so the bilinear (and mip) tap at a plate edge blends the neighbouring cell in.
 * The five unused cells used to be all-zero, which decodes to a normal in the
 * plate plane at the deepest groove height with `AO 0` — the black hairline on
 * the row-5 honours and on Chun (task 261119-2029). They now carry
 * {@link buildNeutralCells}'s values, so a boundary blend is open-face-with-
 * open-face. `bake-relief3d.mjs --check` and this module's tests both gate it.
 */
export const PINNED_RELIEF3D_ATLASES = {
  face_albedo: {
    file: 'relief3d/face_albedo.png',
    width: 1536,
    height: 2380,
    bytes: 458909,
    sha256: '9bd5e4f08018c362da39d969a1928b838430ffbe286708e3822a0c72675502d7',
  },
  face_normal_depth: {
    file: 'relief3d/face_normal_depth.png',
    width: 1536,
    height: 2380,
    bytes: 1567000,
    sha256: '46ce116edd74da3cbc64a93d49e99520f2b632cc414344ff612a7a370e49a154',
  },
  face_ao_roughness: {
    file: 'relief3d/face_ao_roughness.png',
    width: 1536,
    height: 2380,
    bytes: 972171,
    sha256: '43715ae72fb454ae9e0ba48ac29be7c23445bcf549e75511564a37bbae1a60d3',
  },
} as const;

/** Manifest path for the 3D-owned carve set, relative to `public/table/`. */
export const RELIEF3D_MANIFEST_PATH = 'table/relief3d.json';

/** The manifest's atlas keys, in the order the bridge creates textures. */
export type ReliefAtlasKey = keyof typeof PINNED_RELIEF3D_ATLASES;

/** One GPU texture's role in the carved face shader. */
export type ReliefTextureRole = 'albedo' | 'normalDepth' | 'aoRoughness';

/** Manifest atlas key -> shader role. */
export const RELIEF_ATLAS_ROLE: Readonly<
  Record<ReliefAtlasKey, ReliefTextureRole>
> = {
  face_albedo: 'albedo',
  face_normal_depth: 'normalDepth',
  face_ao_roughness: 'aoRoughness',
};

/** Roles in creation order, so a partial failure disposes what exists. */
export const RELIEF_TEXTURE_ROLES: readonly ReliefTextureRole[] = [
  'albedo',
  'normalDepth',
  'aoRoughness',
];

/** sRGB for pigment, linear data for the normal/height and AO/roughness maps. */
export const RELIEF_ROLE_COLOR_SPACE: Readonly<
  Record<ReliefTextureRole, 'srgb' | 'linear'>
> = {
  albedo: 'srgb',
  normalDepth: 'linear',
  aoRoughness: 'linear',
};

/**
 * Tier settings. The face maps are already oversampled on screen (§2.5), so the
 * `compat` tier halves each axis (768 x 1190) to cut GPU memory roughly 4x;
 * POM step counts are a later unit's concern. Anisotropy is clamped to the
 * renderer's reported maximum by the caller.
 */
export const RELIEF_TIER_SETTINGS: Readonly<
  Record<
    QualityTier,
    { readonly scale: number; readonly anisotropy: number; readonly mipmaps: boolean }
  >
> = {
  high: { scale: 1, anisotropy: 8, mipmaps: true },
  balanced: { scale: 1, anisotropy: 4, mipmaps: true },
  compat: { scale: 0.5, anisotropy: 2, mipmaps: true },
};

/** One baked face's address in the atlases. */
export interface ReliefFaceCell {
  readonly face: TileFaceId;
  /** Atlas cell index, 0..36. */
  readonly index: number;
  readonly column: number;
  readonly row: number;
  /** Cell origin in atlas pixels (top-left, y down). */
  readonly x: number;
  readonly y: number;
  /** Normalized `[u0, v0, u1, v1]` rect, top-left origin, V down. */
  readonly rect: readonly [number, number, number, number];
}

/** One pinned atlas entry, validated against the committed manifest. */
export interface ReliefAtlasEntry {
  readonly key: ReliefAtlasKey;
  readonly role: ReliefTextureRole;
  readonly file: string;
  readonly width: number;
  readonly height: number;
  readonly bytes: number;
  readonly sha256: string;
}

/** The validated manifest, in the bridge's own vocabulary. */
export interface ReliefManifest {
  readonly version: typeof RELIEF_VERSION;
  readonly cellWidth: number;
  readonly cellHeight: number;
  readonly columns: number;
  readonly rows: number;
  readonly atlasWidth: number;
  readonly atlasHeight: number;
  readonly plateUnits: readonly [number, number];
  readonly atlases: Readonly<Record<ReliefAtlasKey, ReliefAtlasEntry>>;
  readonly cells: ReadonlyMap<TileFaceId, ReliefFaceCell>;
}

/** The failure classes the bridge reports in its one warning. */
export type ReliefAssetErrorCode =
  | 'manifest-fetch'
  | 'manifest-json'
  | 'manifest-shape'
  | 'manifest-version'
  | 'manifest-atlases'
  | 'manifest-faces'
  | 'manifest-cell'
  | 'atlas-fetch'
  | 'atlas-bytes'
  | 'atlas-hash'
  | 'texture';

/** A typed, reportable load failure. Always triggers the fallback. */
export class ReliefAssetError extends Error {
  readonly code: ReliefAssetErrorCode;

  constructor(code: ReliefAssetErrorCode, message: string) {
    super(message);
    this.name = 'ReliefAssetError';
    this.code = code;
  }
}

function fail(code: ReliefAssetErrorCode, message: string): never {
  throw new ReliefAssetError(code, message);
}

/** Raw RGBA pixels, used by the procedural neutral cells. */
export interface ReliefPixels {
  readonly width: number;
  readonly height: number;
  /** Row-major RGBA, 8 bits per channel. */
  readonly data: Uint8ClampedArray;
}

/** Size of the procedural neutral cell per axis. */
export const NEUTRAL_CELL_SIZE = 64;

/**
 * The fallback cell's flat tangent normal: +Z out, encoded as 8-bit RGB.
 * 128 is the nearest byte to the 0.5 midpoint, matching the bake's `rint`.
 */
const FLAT_NORMAL = [128, 128, 255] as const;

/** Resin roughness (0.45) in 8-bit, the committed open-face value. */
const RESIN_ROUGHNESS_8BIT = 115;

/**
 * Build one channel's 64 x 64 neutral cell, in code and with no asset.
 *
 * - `albedo`: white pigment with a zero paint mask (the shader tints the resin
 *   `#f5f0eb`), so an un-baked face reads as plain ivory.
 * - `normalDepth`: flat normal, height 1 (uncarved).
 * - `aoRoughness`: fully open AO (1.0) and resin roughness 0.45.
 */
export function buildNeutralCell(role: ReliefTextureRole): ReliefPixels {
  const size = NEUTRAL_CELL_SIZE;
  const data = new Uint8ClampedArray(size * size * 4);
  for (let pixel = 0; pixel < size * size; pixel++) {
    const offset = pixel * 4;
    if (role === 'albedo') {
      data[offset] = 255;
      data[offset + 1] = 255;
      data[offset + 2] = 255;
      data[offset + 3] = 0;
    } else if (role === 'normalDepth') {
      data[offset] = FLAT_NORMAL[0];
      data[offset + 1] = FLAT_NORMAL[1];
      data[offset + 2] = FLAT_NORMAL[2];
      data[offset + 3] = 255;
    } else {
      data[offset] = 255;
      data[offset + 1] = RESIN_ROUGHNESS_8BIT;
      data[offset + 2] = 0;
      data[offset + 3] = 255;
    }
  }
  return { width: size, height: size, data };
}

/** The three procedural neutral cells, shared by the fallback and its tests. */
export function buildNeutralCells(): Readonly<
  Record<ReliefTextureRole, ReliefPixels>
> {
  return {
    albedo: buildNeutralCell('albedo'),
    normalDepth: buildNeutralCell('normalDepth'),
    aoRoughness: buildNeutralCell('aoRoughness'),
  };
}

/** Upload size for a tier's atlases. */
export function reliefTextureSize(tier: QualityTier): {
  readonly width: number;
  readonly height: number;
} {
  const scale = RELIEF_TIER_SETTINGS[tier].scale;
  return {
    width: Math.round(RELIEF_RASTER.atlasWidth * scale),
    height: Math.round(RELIEF_RASTER.atlasHeight * scale),
  };
}

/**
 * The atlas upload scale a tier uses (3D-11 reads this).
 *
 * `high` and `balanced` share the full-resolution upload; only `compat` halves
 * it. A tier change within the same scale must not re-decode and re-upload ~58
 * MB of atlas — that is exactly the work a struggling device cannot afford — so
 * the scene reloads only when this number changes.
 */
export function reliefUploadScale(tier: QualityTier): number {
  return RELIEF_TIER_SETTINGS[tier].scale;
}

/**
 * GPU bytes for one texture, including the mip chain (x4/3, the §2.5
 * arithmetic). `58.5 MB` for all three at `high`, `14.6 MB` at `compat`.
 */
export function reliefTextureBytes(
  width: number,
  height: number,
  mipmaps: boolean,
): number {
  const base = width * height * 4;
  return mipmaps ? Math.round((base * 4) / 3) : base;
}

/** Per-role and total GPU bytes for a tier, before any renderer clamping. */
export function reliefGpuBytes(tier: QualityTier): {
  readonly byRole: Readonly<Record<ReliefTextureRole, number>>;
  readonly total: number;
} {
  const { width, height } = reliefTextureSize(tier);
  const perTexture = reliefTextureBytes(
    width,
    height,
    RELIEF_TIER_SETTINGS[tier].mipmaps,
  );
  const byRole = {
    albedo: perTexture,
    normalDepth: perTexture,
    aoRoughness: perTexture,
  };
  return {
    byRole,
    total: perTexture * RELIEF_TEXTURE_ROLES.length,
  };
}

/**
 * What the host's texture factory receives for one atlas. Exactly one of
 * `bytes` (committed PNG) and `pixels` (procedural fallback) is set.
 */
export interface ReliefTextureRequest {
  readonly role: ReliefTextureRole;
  /** Stable debug name, e.g. `relief-face-albedo`. */
  readonly name: string;
  /** PNG payload for the committed path; decode at `width` x `height`. */
  readonly bytes: Uint8Array | null;
  /** Raw RGBA for the procedural path; upload as a data texture. */
  readonly pixels: ReliefPixels | null;
  /** Upload size in texels (the compat tier halves the atlas). */
  readonly width: number;
  readonly height: number;
  readonly colorSpace: 'srgb' | 'linear';
  /** Never flip: the manifest's cells are y-down and the mesh's V is y-down. */
  readonly flipY: false;
  readonly generateMipmaps: boolean;
  readonly anisotropy: number;
}

/** A live GPU texture the bridge can dispose. */
export interface ReliefTextureHandle {
  dispose(): void;
}

/**
 * The host's texture seam. 3D-02/3D-05 supply the three.js implementation:
 * decode `bytes` to an image at `width` x `height` (or upload `pixels` as a
 * `DataTexture`), set `colorSpace`, `flipY`, mipmaps, anisotropy and
 * clamp-to-edge wrapping, then hand back a disposable handle.
 */
export interface ReliefTextureFactory<
  TTexture extends ReliefTextureHandle = ReliefTextureHandle,
> {
  create(request: ReliefTextureRequest): TTexture | Promise<TTexture>;
}

/**
 * How the atlases' digests were computed.
 *
 * `webcrypto` is the normal path. `javascript` means `crypto.subtle` was missing
 * — which only happens outside a **secure context**, i.e. any plain-HTTP origin
 * other than `localhost` — and the bridge verified the same pins with
 * `sha256.sha256HexSync` instead. The carve is still the committed carve, but the
 * origin is worth knowing about (it also turns off other web-platform features),
 * so it is reported rather than swallowed.
 */
export type ReliefVerification = 'webcrypto' | 'javascript';

/** The loaded bridge. `cellForFace` is null for `blank` (no baked art). */
export interface ReliefAssets<
  TTexture extends ReliefTextureHandle = ReliefTextureHandle,
> {
  readonly status: ReliefStatus;
  readonly tier: QualityTier;
  /**
   * Which SHA-256 verified the committed atlases, or null on the fallback path
   * (nothing was verified there). See {@link ReliefVerification}.
   */
  readonly verification: ReliefVerification | null;
  readonly textures: Readonly<Record<ReliefTextureRole, TTexture>>;
  /** GPU bytes for the three textures at this tier, mips included. */
  readonly atlasBytes: number;
  readonly bytesByRole: Readonly<Record<ReliefTextureRole, number>>;
  /** Baked cells; the fallback maps every face id to the neutral cell. */
  readonly faces: ReadonlyMap<TileFaceId, ReliefFaceCell>;
  /** The carved plate's size in tile units. */
  readonly plateUnits: { readonly width: number; readonly height: number };
  /** Atlas rect for a baked face, or null for `blank`/no art. */
  cellForFace(face: TileFaceId): ReliefFaceCell | null;
  /** Narrow an unknown id to the face vocabulary, then resolve it (unknown -> `blank`). */
  resolveCell(value: unknown): ReliefFaceCell | null;
  /** Idempotent; disposes every texture this bridge created. */
  dispose(): void;
}

/** The structural subset of `Response` the bridge needs. */
export interface ReliefFetchResponse {
  readonly ok: boolean;
  readonly status?: number;
  arrayBuffer(): Promise<ArrayBuffer>;
}

export type ReliefFetch = (url: string) => Promise<ReliefFetchResponse>;

/** Everything the loader needs; all platform bits are injectable for tests. */
export interface LoadReliefOptions<
  TTexture extends ReliefTextureHandle = ReliefTextureHandle,
> {
  readonly tier: QualityTier;
  /** App base URL, e.g. `import.meta.env.BASE_URL`. `'/table/relief.json'` for `'/'`. */
  readonly baseUrl: string;
  readonly createTexture: ReliefTextureFactory<TTexture>;
  /** Renderer's `MAX_TEXTURE_ANISOTROPY`; the tier value is clamped to it. */
  readonly maxAnisotropy?: number;
  readonly fetchImpl?: ReliefFetch;
  /** Defaults to `console.warn`; called once, only on the fallback path. */
  readonly warn?: (message: string) => void;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function record(value: unknown, what: string): Record<string, unknown> {
  if (!isRecord(value)) fail('manifest-shape', `${what} must be an object`);
  return value;
}

function finiteNumber(value: unknown, what: string): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    fail('manifest-shape', `${what} must be a finite number`);
  }
  return value;
}

function integer(value: unknown, what: string): number {
  const number = finiteNumber(value, what);
  if (!Number.isInteger(number)) fail('manifest-shape', `${what} must be an integer`);
  return number;
}

function joinUrl(baseUrl: string, path: string): string {
  const left = baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`;
  const right = path.startsWith('/') ? path.slice(1) : path;
  return `${left}${right}`;
}

/**
 * Parse and validate a manifest against the pinned contract.
 *
 * Throws {@link ReliefAssetError} for a version mismatch, a missing/extra face,
 * a non-normalized or inconsistent rect, or an atlas pin mismatch. The caller
 * turns that into the procedural fallback, with the code in the warning.
 */
export function parseReliefManifest(
  value: unknown,
  pins: Readonly<Record<ReliefAtlasKey, ReliefAtlasPin>> = PINNED_RELIEF3D_ATLASES,
): ReliefManifest {
  const manifest = record(value, 'relief manifest');

  if (integer(manifest.version, 'version') !== RELIEF_VERSION) {
    fail(
      'manifest-version',
      `relief manifest version ${String(manifest.version)} is not ${RELIEF_VERSION}`,
    );
  }

  const raster = record(manifest.raster, 'raster');
  const rasterPins = {
    cellWidth: RELIEF_RASTER.cellWidth,
    cellHeight: RELIEF_RASTER.cellHeight,
    columns: RELIEF_RASTER.columns,
    rows: RELIEF_RASTER.rows,
    atlasWidth: RELIEF_RASTER.atlasWidth,
    atlasHeight: RELIEF_RASTER.atlasHeight,
  } as const;
  for (const key of Object.keys(rasterPins) as (keyof typeof rasterPins)[]) {
    if (integer(raster[key], `raster.${key}`) !== rasterPins[key]) {
      fail(
        'manifest-shape',
        `raster.${key} is ${String(raster[key])}, pinned at ${rasterPins[key]}`,
      );
    }
  }
  if (integer(raster.faces, 'raster.faces') !== RELIEF_RASTER.faceCount) {
    fail(
      'manifest-shape',
      `raster.faces is ${String(raster.faces)}, pinned at ${RELIEF_RASTER.faceCount}`,
    );
  }

  if (
    !Array.isArray(raster.plateUnits) ||
    raster.plateUnits.length !== 2 ||
    Math.abs(finiteNumber(raster.plateUnits[0], 'plateUnits[0]') - RELIEF_PLATE_UNITS[0]) >
      1e-9 ||
    Math.abs(finiteNumber(raster.plateUnits[1], 'plateUnits[1]') - RELIEF_PLATE_UNITS[1]) >
      1e-9
  ) {
    fail(
      'manifest-shape',
      `raster.plateUnits is not the committed ${RELIEF_PLATE_UNITS.join(' x ')} units`,
    );
  }
  // The mesh's plateau and the atlas cells must describe the same rectangle.
  if (
    Math.abs(TILE.facePlateWidthUnits - RELIEF_PLATE_UNITS[0]) > 1e-9 ||
    Math.abs(TILE.facePlateHeightUnits - RELIEF_PLATE_UNITS[1]) > 1e-9
  ) {
    fail(
      'manifest-shape',
      'relief plate does not match the committed tile face plate',
    );
  }

  const atlasSource = record(manifest.atlases, 'atlases');
  const atlases = {} as Record<ReliefAtlasKey, ReliefAtlasEntry>;
  for (const key of Object.keys(pins) as ReliefAtlasKey[]) {
    const pin = pins[key];
    const entry = record(atlasSource[key], `atlases.${key}`);
    if (entry.file !== pin.file) {
      fail('manifest-atlases', `atlases.${key}.file is not ${pin.file}`);
    }
    for (const field of ['width', 'height', 'bytes'] as const) {
      if (integer(entry[field], `atlases.${key}.${field}`) !== pin[field]) {
        fail(
          'manifest-atlases',
          `atlases.${key}.${field} is ${String(entry[field])}, pinned at ${pin[field]}`,
        );
      }
    }
    const sha = record(entry.sha256, `atlases.${key}.sha256`);
    if (sha.png !== pin.sha256) {
      fail('manifest-atlases', `atlases.${key}.sha256.png is not the pinned hash`);
    }
    atlases[key] = {
      key,
      role: RELIEF_ATLAS_ROLE[key],
      file: pin.file,
      width: pin.width,
      height: pin.height,
      bytes: pin.bytes,
      sha256: pin.sha256,
    };
  }

  const faceSource = record(manifest.faces, 'faces');
  const keys = Object.keys(faceSource);
  if (keys.length !== RELIEF_FACE_IDS.length) {
    fail(
      'manifest-faces',
      `manifest has ${keys.length} faces, expected ${RELIEF_FACE_IDS.length}`,
    );
  }
  const cells = new Map<TileFaceId, ReliefFaceCell>();
  const usedCells = new Set<number>();
  keys.forEach((key, position) => {
    const expectedFace = RELIEF_FACE_IDS[position];
    if (key !== expectedFace) {
      fail(
        'manifest-faces',
        `face ${position} is ${JSON.stringify(key)}, expected ${JSON.stringify(expectedFace)} (atlas order)`,
      );
    }
    if (!isTileFaceId(key)) {
      fail('manifest-faces', `unknown face id ${JSON.stringify(key)}`);
    }
    const face = key;
    const entry = record(faceSource[face], `faces.${face}`);
    const cell = record(entry.cell, `faces.${face}.cell`);
    const index = integer(cell.index, `faces.${face}.cell.index`);
    const column = integer(cell.column, `faces.${face}.cell.column`);
    const row = integer(cell.row, `faces.${face}.cell.row`);
    const x = integer(cell.x, `faces.${face}.cell.x`);
    const y = integer(cell.y, `faces.${face}.cell.y`);

    if (column < 0 || column >= RELIEF_RASTER.columns) {
      fail('manifest-cell', `faces.${face}.cell.column is out of range`);
    }
    if (row < 0 || row >= RELIEF_RASTER.rows) {
      fail('manifest-cell', `faces.${face}.cell.row is out of range`);
    }
    if (index !== row * RELIEF_RASTER.columns + column) {
      fail('manifest-cell', `faces.${face}.cell.index disagrees with row/column`);
    }
    if (usedCells.has(index)) {
      fail('manifest-cell', `faces.${face}.cell.index ${index} is used twice`);
    }
    usedCells.add(index);
    if (x !== column * RELIEF_RASTER.cellWidth) {
      fail('manifest-cell', `faces.${face}.cell.x disagrees with column`);
    }
    if (y !== row * RELIEF_RASTER.cellHeight) {
      fail('manifest-cell', `faces.${face}.cell.y disagrees with row`);
    }

    const expectedRect = [
      x / RELIEF_RASTER.atlasWidth,
      y / RELIEF_RASTER.atlasHeight,
      (x + RELIEF_RASTER.cellWidth) / RELIEF_RASTER.atlasWidth,
      (y + RELIEF_RASTER.cellHeight) / RELIEF_RASTER.atlasHeight,
    ] as const;
    if (
      !Array.isArray(cell.rect) ||
      cell.rect.length !== 4 ||
      cell.rect.some((value) => typeof value !== 'number' || !Number.isFinite(value))
    ) {
      fail('manifest-cell', `faces.${face}.cell.rect must be four finite numbers`);
    }
    cell.rect.forEach((value, axis) => {
      const number = value as number;
      if (number < 0 || number > 1) {
        fail('manifest-cell', `faces.${face}.cell.rect[${axis}] is not normalized`);
      }
      if (Math.abs(number - expectedRect[axis]) > 1e-6) {
        fail(
          'manifest-cell',
          `faces.${face}.cell.rect[${axis}] does not match the pinned cell`,
        );
      }
    });

    cells.set(face, {
      face,
      index,
      column,
      row,
      x,
      y,
      rect: [
        cell.rect[0] as number,
        cell.rect[1] as number,
        cell.rect[2] as number,
        cell.rect[3] as number,
      ],
    });
  });

  if (cells.size !== RELIEF_RASTER.faceCount) {
    fail(
      'manifest-faces',
      `resolved ${cells.size} faces, expected ${RELIEF_RASTER.faceCount}`,
    );
  }

  return {
    version: RELIEF_VERSION,
    cellWidth: RELIEF_RASTER.cellWidth,
    cellHeight: RELIEF_RASTER.cellHeight,
    columns: RELIEF_RASTER.columns,
    rows: RELIEF_RASTER.rows,
    atlasWidth: RELIEF_RASTER.atlasWidth,
    atlasHeight: RELIEF_RASTER.atlasHeight,
    plateUnits: RELIEF_PLATE_UNITS,
    atlases,
    cells,
  };
}

/**
 * SHA-256 of `bytes`, with how it was computed.
 *
 * WebCrypto first (native and fast). Outside a secure context `crypto.subtle` is
 * undefined — a plain-HTTP LAN or tailnet origin is *not* secure — so the
 * fallback is the bridge's own implementation over the same bytes, against the
 * same pins. Before this, that case threw `hash-unavailable` and the whole view
 * silently fell back to the procedural cells: the art was lost on any
 * self-hosted HTTP URL, which is exactly how the defect was found.
 */
async function sha256Hex(
  bytes: Uint8Array,
): Promise<{ readonly digest: string; readonly how: ReliefVerification }> {
  const subtle = globalThis.crypto?.subtle;
  if (!subtle) {
    return { digest: sha256HexSync(bytes), how: 'javascript' };
  }
  const digest = await subtle.digest('SHA-256', bytes);
  return {
    digest: [...new Uint8Array(digest)]
      .map((byte) => byte.toString(16).padStart(2, '0'))
      .join(''),
    how: 'webcrypto',
  };
}

async function fetchBytes(
  fetchImpl: ReliefFetch,
  url: string,
  what: string,
  fetchCode: 'manifest-fetch' | 'atlas-fetch',
): Promise<Uint8Array> {
  let response: ReliefFetchResponse;
  try {
    response = await fetchImpl(url);
  } catch (error) {
    fail(fetchCode, `${what} ${url} could not be fetched: ${describeError(error)}`);
  }
  if (!response.ok) {
    fail(fetchCode, `${what} ${url} returned HTTP ${response.status ?? '?'}`);
  }
  try {
    return new Uint8Array(await response.arrayBuffer());
  } catch (error) {
    fail(fetchCode, `${what} ${url} could not be read: ${describeError(error)}`);
  }
}

function describeError(error: unknown): string {
  if (error instanceof Error) return error.message;
  return String(error);
}

function anisotropyFor(
  tier: QualityTier,
  maxAnisotropy: number | undefined,
): number {
  const wanted = RELIEF_TIER_SETTINGS[tier].anisotropy;
  if (maxAnisotropy === undefined) return wanted;
  if (!Number.isFinite(maxAnisotropy) || maxAnisotropy < 1) return 1;
  return Math.min(wanted, Math.floor(maxAnisotropy));
}

function committedRequest(
  atlas: ReliefAtlasEntry,
  bytes: Uint8Array,
  tier: QualityTier,
  anisotropy: number,
): ReliefTextureRequest {
  const { width, height } = reliefTextureSize(tier);
  return {
    role: atlas.role,
    name: `relief-${atlas.role}`,
    bytes,
    pixels: null,
    width,
    height,
    colorSpace: RELIEF_ROLE_COLOR_SPACE[atlas.role],
    flipY: false,
    generateMipmaps: RELIEF_TIER_SETTINGS[tier].mipmaps,
    anisotropy,
  };
}

function neutralRequest(
  role: ReliefTextureRole,
  pixels: ReliefPixels,
  tier: QualityTier,
  anisotropy: number,
): ReliefTextureRequest {
  return {
    role,
    name: `relief-${role}-fallback`,
    bytes: null,
    pixels,
    width: pixels.width,
    height: pixels.height,
    colorSpace: RELIEF_ROLE_COLOR_SPACE[role],
    flipY: false,
    generateMipmaps: RELIEF_TIER_SETTINGS[tier].mipmaps,
    anisotropy,
  };
}

function fallbackCells(): Map<TileFaceId, ReliefFaceCell> {
  const cells = new Map<TileFaceId, ReliefFaceCell>();
  const neutral: Omit<ReliefFaceCell, 'face'> = {
    index: 0,
    column: 0,
    row: 0,
    x: 0,
    y: 0,
    rect: [0, 0, 1, 1],
  };
  for (const face of [...RELIEF_FACE_IDS, 'blank'] as TileFaceId[]) {
    cells.set(face, { face, ...neutral });
  }
  return cells;
}

function createAssets<TTexture extends ReliefTextureHandle>(options: {
  readonly status: ReliefStatus;
  readonly tier: QualityTier;
  /** Which SHA-256 verified the atlases, or null on the fallback path. */
  readonly verification: ReliefVerification | null;
  readonly textures: Readonly<Record<ReliefTextureRole, TTexture>>;
  readonly bytesByRole: Readonly<Record<ReliefTextureRole, number>>;
  readonly faces: ReadonlyMap<TileFaceId, ReliefFaceCell>;
  readonly plateUnits: { readonly width: number; readonly height: number };
}): ReliefAssets<TTexture> {
  let disposed = false;
  const textureList = RELIEF_TEXTURE_ROLES.map((role) => options.textures[role]);
  return {
    status: options.status,
    tier: options.tier,
    verification: options.verification,
    textures: options.textures,
    bytesByRole: options.bytesByRole,
    faces: options.faces,
    plateUnits: options.plateUnits,
    atlasBytes: RELIEF_TEXTURE_ROLES.reduce(
      (total, role) => total + options.bytesByRole[role],
      0,
    ),
    cellForFace(face) {
      return options.faces.get(face) ?? null;
    },
    resolveCell(value) {
      return options.faces.get(isTileFaceId(value) ? value : 'blank') ?? null;
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      for (const texture of textureList) texture.dispose();
    },
  };
}

/**
 * Load the 3D-owned carve set (3D-17): the decal-profile normal/height and
 * AO/roughness plus the committed albedo.
 *
 * The file paths come from the manifest (`relief/…` and `relief3d/…` are both
 * relative to `public/table/`), and the pins are validated exactly like the
 * committed set, so a missing or off-pin bake falls through to the committed
 * relief rather than rendering silently wrong.
 */
async function loadRelief3d<TTexture extends ReliefTextureHandle>(
  options: LoadReliefOptions<TTexture>,
  fetchImpl: ReliefFetch,
  anisotropy: number,
): Promise<ReliefAssets<TTexture>> {
  const manifestBytes = await fetchBytes(
    fetchImpl,
    joinUrl(options.baseUrl, RELIEF3D_MANIFEST_PATH),
    'relief3d manifest',
    'manifest-fetch',
  );
  let raw: unknown;
  try {
    raw = JSON.parse(new TextDecoder().decode(manifestBytes));
  } catch (error) {
    fail('manifest-json', `relief3d manifest is not JSON: ${describeError(error)}`);
  }
  const manifest = parseReliefManifest(raw, PINNED_RELIEF3D_ATLASES);

  const payloads = {} as Record<ReliefAtlasKey, Uint8Array>;
  let verification: ReliefVerification | null = null;
  for (const key of Object.keys(PINNED_RELIEF3D_ATLASES) as ReliefAtlasKey[]) {
    const pin = PINNED_RELIEF3D_ATLASES[key];
    const bytes = await fetchBytes(
      fetchImpl,
      joinUrl(options.baseUrl, `table/${pin.file}`),
      `relief3d atlas ${key}`,
      'atlas-fetch',
    );
    if (bytes.byteLength !== pin.bytes) {
      fail('atlas-bytes', `${pin.file} is ${bytes.byteLength} bytes, pinned at ${pin.bytes}`);
    }
    const hashed = await sha256Hex(bytes);
    if (hashed.digest !== pin.sha256) {
      fail('atlas-hash', `${pin.file} SHA-256 does not match the pin`);
    }
    verification = verification ?? hashed.how;
    payloads[key] = bytes;
  }

  const created: TTexture[] = [];
  const textures = {} as Record<ReliefTextureRole, TTexture>;
  try {
    for (const key of Object.keys(PINNED_RELIEF3D_ATLASES) as ReliefAtlasKey[]) {
      const atlas = manifest.atlases[key];
      const texture = await options.createTexture.create(
        committedRequest(atlas, payloads[key], options.tier, anisotropy),
      );
      textures[atlas.role] = texture;
      created.push(texture);
    }
  } catch (error) {
    for (const texture of created) texture.dispose();
    fail('texture', `could not create relief3d textures: ${describeError(error)}`);
  }

  const { width, height } = reliefTextureSize(options.tier);
  const perTexture = reliefTextureBytes(
    width,
    height,
    RELIEF_TIER_SETTINGS[options.tier].mipmaps,
  );
  return createAssets({
    status: 'relief3d',
    verification,
    tier: options.tier,
    textures,
    bytesByRole: { albedo: perTexture, normalDepth: perTexture, aoRoughness: perTexture },
    faces: manifest.cells,
    plateUnits: {
      width: manifest.plateUnits[0],
      height: manifest.plateUnits[1],
    },
  });
}

async function loadFallback<TTexture extends ReliefTextureHandle>(
  options: LoadReliefOptions<TTexture>,
  anisotropy: number,
): Promise<ReliefAssets<TTexture>> {
  const cells = buildNeutralCells();
  const textures = {} as Record<ReliefTextureRole, TTexture>;
  const created: TTexture[] = [];
  try {
    for (const role of RELIEF_TEXTURE_ROLES) {
      const texture = await options.createTexture.create(
        neutralRequest(role, cells[role], options.tier, anisotropy),
      );
      textures[role] = texture;
      created.push(texture);
    }
  } catch (error) {
    for (const texture of created) texture.dispose();
    fail('texture', `could not create the fallback cell: ${describeError(error)}`);
  }

  if (RELIEF_TEXTURE_ROLES.some((role) => !textures[role])) {
    fail('texture', 'the fallback cell did not produce all three textures');
  }
  const perTexture = reliefTextureBytes(
    NEUTRAL_CELL_SIZE,
    NEUTRAL_CELL_SIZE,
    RELIEF_TIER_SETTINGS[options.tier].mipmaps,
  );
  return createAssets({
    status: 'fallback',
    verification: null,
    tier: options.tier,
    textures,
    bytesByRole: {
      albedo: perTexture,
      normalDepth: perTexture,
      aoRoughness: perTexture,
    },
    faces: fallbackCells(),
    plateUnits: {
      width: TILE.facePlateWidthUnits,
      height: TILE.facePlateHeightUnits,
    },
  });
}

/**
 * Load the committed relief atlases, or the procedural neutral cell if anything
 * is missing, invalid or off-pin. Never throws for an asset problem: the
 * returned `status` is the truth, and exactly one warning is emitted on the
 * fallback path.
 */
export async function loadReliefAssets<TTexture extends ReliefTextureHandle>(
  options: LoadReliefOptions<TTexture>,
): Promise<ReliefAssets<TTexture>> {
  const fetchImpl: ReliefFetch =
    options.fetchImpl ?? ((url) => fetch(url));
  const warn =
    options.warn ?? ((message: string) => console.warn(message));
  const anisotropy = anisotropyFor(options.tier, options.maxAnisotropy);
  try {
    const assets = await loadRelief3d(options, fetchImpl, anisotropy);
    if (assets.verification === 'javascript') {
      // Not a failure — the committed pins still verified — but the origin is not
      // a secure context, which is worth saying out loud: the fix is to serve
      // over HTTPS, and `measure().reliefVerification` reports it too.
      warn(
        '[3d] relief3d atlases verified with the JavaScript SHA-256 fallback: this origin is not a ' +
          'secure context (crypto.subtle is unavailable outside HTTPS/localhost). The carved art is ' +
          'the committed art; serve over HTTPS to use WebCrypto.',
      );
    }
    return assets;
  } catch (error) {
    const code = error instanceof ReliefAssetError ? error.code : 'manifest-shape';
    warn(
      `[3d] relief3d carve unavailable (${code}: ${describeError(error)}); using the procedural neutral cell`,
    );
    return loadFallback(options, anisotropy);
  }
}
